custom_css:
/*┌─────────────────────────┐
  │     【 变 量 目 录 】     │
  └─────────────────────────┘*/

:root {
    --文本色: var(--SmartThemeBodyColor);
    --斜体色: var(--SmartThemeEmColor);
    --划线色: var(--SmartThemeUnderlineColor);
    --引用色: var(--SmartThemeQuoteColor);
    --阴影色: var(--SmartThemeShadowColor);
    --聊天色: var(--SmartThemeChatTintColor);
    --背景色: var(--SmartThemeBlurTintColor);
    --边框色: var(--SmartThemeBorderColor);
    --用户色: var(--SmartThemeUserMesBlurTintColor);
    --AI色: var(--SmartThemeBotMesBlurTintColor);
    --topBarBlockSize: var(--顶栏高度, 2.3em);
    --顶栏高度: 2.3em;
    --不透明: 1;
    --微透明: 0.8;
    --半透明: 0.6;
    --高透明: 0.4;
    --深透明: 0.2;

/*——————▽界面基础▽——————*/

    --重点色: var(--划线色);
    --次点色: var(--引用色);

    --系统通知色:var(--次点色);

    --滚动条色: var(--边框色);
    --滚动条宽: 0.45em;

    --界面边距: 0.5em;
    --全局角: 30px;

    --美化角: 130px;
    --美化框: 0.2em;

   /*〖❷.1.2 顶栏图标(美化）〗*/
    --顶栏图标: "✝︎";
    --顶栏图标大小: 1.4em;

   /*〖❷.1.7 底栏图标(美化)〗*/
    --底栏图标左1: "✦";
    --底栏图标左2: "✧";
    --底栏图标右: "✦";
    --底栏图标大小: 0.8em;

    --世界书按键对齐: -2.2em;


/*——————▽聊天气泡▽——————*/

    --气泡间距: 4em;
    --聊天底高: 6em;

   /*〖❶.6.2 铅笔图标(美化)〗*/
    --铅笔大小: calc(var(--mainFontSize) * 0.9);

    --U气泡宽度: 80%;
    --U整体缩放: 0.9;
    --U头像大小: 1;
    --U楼层上下: 3.5em;
    --U楼层左右: -5.5em;

   /*〖❶.2.3 推理头部(美化)〗*/
    --推理图标: "✶";
    --推理图标色: var(--重点色);
    --推理图标大小: 2em;
    --推理内容高: 400px;

    --C文本边距: 3%;
    --C文本行距: 1.8;
    --C文本段距: 1.5em;
    --C楼层上下: -50px;

    --C图片高度: 210px;
    --C图片缩放: 1;
    --C图片取景: 50% 35%;
    --C图片渐变: linear-gradient(to bottom, rgba(0, 0, 0, 1) 50%, rgba(0, 0, 0, 0) 100%);
    --C图片灰度: grayscale(50%) opacity(var(--不透明));


/*——————▽底色边框▽——————*/

   /*〖❸.1 主标题〗*/
    --标题底框色: rgb(from var(--边框色) r g b / var(--半透明));

   /*〖❸.2.1 聚焦边〗*/
    --聚焦边框色: rgb(from var(--次点色) r g b / var(--高透明));

   /*〖❸.2.2 文本域〗*/
    --文本域底色: rgb(from var(--阴影色) r g b / var(--高透明));
    --自定义框色: rgb(from var(--聊天色) r g b / var(--不透明));

   /*〖❸.3 选择器〗*/
    --选择器底色: rgb(from var(--聊天色) r g b / var(--高透明));
    --选择器字色: rgb(from var(--文本色) r g b / var(--微透明));

    --开启条目色: rgb(from var(--标题底框色) r g b / calc(alpha - 0.2));
    --世界书条目色: rgb(from var(--文本色) r g b / calc(alpha - 0.95));


/*——————▽组件杂物▽——————*/

   /*〖❸.4.4 收起&展开按钮〗*/
    --收起图标: "•";
    --收起图标色: rgb(from var(--文本色) r g b / var(--高透明));
    --展开图标: "•";
    --展开图标色: var(--重点色);

   /*〖❸.4.5 勾选框〗*/
    --勾选图标: "✦";
    --勾选图标大小: 1.4em;
    --勾选图标上下: 3px;
    --勾选图标色: var(--重点色);
    --勾选框底色: var(--标题底框色);

    --滑条轨道色: var(--选择器底色);
    --滑条滑块色: rgb(from var(--标题底框色) r g b / calc(alpha + 1));

    --收藏图标: "ʚɞ";
    --收藏图标大小: 25px;
    --收藏图标上下: 90%;
    --收藏图标色: var(--重点色);

}




/*┌─────────────────────────┐
  │     【 ❶ 聊 天 区 】     │
  └─────────────────────────┘*/


/*⋯⋯⋯⋯ ❶.1 聊天设置 ⋯⋯⋯⋯*/


/*〖❶.1.1 聊天画框〗*/

#sheld {
    overflow: hidden !important;
}
#chat {
    border-radius: var(--美化角) var(--美化角) 0 0;
    border: var(--美化框) solid var(--边框色);
    border-bottom: none;
    box-shadow: 0 -800px 0 800px var(--背景色);
}


/*〖❶.1.2 气泡基础〗*/

/*气泡竖排居中*/
.mes,
.mes_block .ch_name,
.mes .alignItemsBaseline {
    align-items: center !important;
    flex-direction: column !important;
    text-align: justify;
}

/*气泡底框边距*/
.mes,
.mes_block,
.mes_text,
.mes_reasoning,
.mes .mesAvatarWrapper {
    background: transparent !important;
    border: none !important;
    margin: 0 !important;
    padding: 0 !important;
}
.mes .name_text {
    margin: 3px 0 !important;
}
.mes_text {
    margin-top: 0.5em !important;
}

/*气泡圆角间距*/
.mes {
    border-radius: var(--全局角) !important;
    margin-bottom: var(--气泡间距) !important;
    padding-bottom: 3em !important;
}
.last_mes {
    margin-bottom: var(--聊天底高) !important;
}
.mes[type="assistant_message"] {
    margin-bottom: 0.5em !important;
}


/*〖❶.1.3 气泡文本〗*/

/*气泡文本边距*/
.mes_text {
    padding: 0 var(--C文本边距) !important;
}

/*User气泡文本*/
.mes[is_user="true"] .mes_text {
    border-radius: var(--全局角);
    background-color: var(--用户色) !important;
    padding: 0.8em 1.2em !important;
}

/*Char气泡文本*/
div[is_user="false"] .mes_text p {
    margin-bottom: var(--C文本段距);
}
.mes[is_user="false"] .mes_text {
    line-height: var(--C文本行距);
}
/*去段尾*/
.mes_text p:last-child {
    margin-bottom: 0 !important;
}


/*⋯⋯⋯⋯ ❶.2 推理设置 ⋯⋯⋯⋯*/


/*〖❶.2.1 推理基础〗*/

/*推理整体居中*/
.mes_reasoning_details {
    margin: 0.5em var(--C文本边距) 1em var(--C文本边距);
}
.mes_reasoning_details .mes_reasoning_summary {
    margin: 0;
}

/*推理头部居中*/
.mes_reasoning_summary {
    align-items: center;
    display: grid;
    grid-template-columns: 1fr auto 1fr;
}
.mes_reasoning_header_block {
    grid-column: 2;
}
.mes_reasoning_actions {
    justify-self: end;
}

/*推理内容边框*/
.mes_reasoning {
    max-height: var(--推理内容高);
    border-radius: var(--全局角);
    border: 0.12em dashed var(--聚焦边框色) !important;
    padding: 0.8em !important;
    padding-left: calc(0.8em + var(--滚动条宽)) !important;
    scrollbar-gutter: stable;
}
.mes_reasoning::-webkit-scrollbar-thumb {
    background-color: rgb(from var(--滚动条色) r g b / var(--微透明)) !important;
}


/*〖❶.2.2 推理头部〗*/

/*隐藏推理头部の箭头*/
.mes_reasoning_arrow {
    display: none;
}
/*隐藏推理头部の文字*/
.mes_reasoning_header_title {
    font-size: 0;
}
/*显示推理头部の秒数*/
.mes_reasoning_header_title::after {
    content: attr(data-duration) "″";
    font-size: calc(var(--mainFontSize) * 0.9);
}

/*推理头部底色*/
.mes_reasoning_header {
    border-radius: var(--全局角);
    background: var(--用户色);
    color: rgb(from var(--文本色) r g b / var(--半透明));
    padding: 0.4em 0.8em;
}
/*内容展开时头部变色*/
.mes_reasoning_details[open] .mes_reasoning_header {
    background: var(--聚焦边框色);
    color: rgb(from var(--文本色) r g b / var(--微透明));
}


/*〖❶.2.3 推理头部(美化)〗*/

/*隐藏推理头部の秒数*/
.mes_reasoning_header_title {
    display: none;
}
/*隐藏推理头部の底色*/
.mes_reasoning_header,
.mes_reasoning_details[open] .mes_reasoning_header {
    background: transparent;
    padding: 0 50px;
}

/*推理头部の图标美化*/
.mes_reasoning_header::before {
    display: inline-block;
    transform-origin: top center;
    content: var(--推理图标);
    color: var(--推理图标色);
    font-size: var(--推理图标大小);
}
/*内容展开时图标动画*/
details[open] .mes_reasoning_header::before {
    animation: swing-anim 3s ease-in-out infinite;
}
@keyframes swing-anim {
    0% { transform: rotate(15deg); }
    50% { transform: rotate(-15deg); }
    100% { transform: rotate(15deg); }
}


/*⋯⋯⋯⋯ ❶.3 气泡状态 ⋯⋯⋯⋯*/


/*〖❶.3.1 删除消息〗*/

/*删除勾选居中*/
.del_checkbox {
    margin: 1em 0 0.6em 0 !important;
}

/*删除气泡底色*/
#chat .mes.selected {
    background-color: var(--边框色) !important;
}
/*清空删除时User文本底色*/
#chat .mes.selected[is_user="true"] .mes_text {
    background-color: transparent !important;
}


/*〖❶.3.2 幽灵消息〗*/

/*幽灵图标放大*/
.mes_ghost {
    position: absolute;
    pointer-events: none;
    left: 50%;
    transform: translateX(-50%);
    opacity: 0.03;
    font-size: 2000%;
}

/*幽灵气泡黑白*/
.mes[is_system="true"]:not(:has(.custom-flex-container)) {
    filter: grayscale(100%) !important;
}
/*清空幽灵时User文本底色*/
.mes[is_system="true"] .mes_text {
    background-color: transparent !important;
}


/*⋯⋯⋯⋯ ❶.4 气泡底部 ⋯⋯⋯⋯*/


/*〖❶.4.1 Char计时计数〗*/

/*去原生盒子影响*/
.mes[is_user="false"] .mesAvatarWrapper {
    transform: none !important;
}
/*Char计时计数位置靠底*/
.mes[is_user="false"] .mes_timer,
.mes[is_user="false"] .tokenCounterDisplay {
    position: absolute;
    bottom: -1px;
    font-weight: 400;
    font-size: 0.8em;
    letter-spacing: 1px;
    padding-left: 1px;
}

/*Char底部の左计时*/
.mes[is_user="false"] .mes_timer {
    justify-self: start;
    left: 52px;
}
.mes[is_user="false"] .mes_timer::before {
    content: "⏱";
}
/*无计时时不显示图标*/
.mes[is_user="false"] .mes_timer:empty::before {
    display: none !important;
}

/*Char底部の右计数*/
.mes[is_user="false"] .tokenCounterDisplay {
    justify-self: end;
    right: 52px;
}
.mes[is_user="false"] .tokenCounterDisplay::before {
    content: "⟠";
}
/*无计数时不显示图标*/
.mes[is_user="false"] .tokenCounterDisplay:empty::before {
    display: none !important;
}


/*〖❶.4.2 气泡底部翻页〗*/

/*底部の页码*/
.swipes-counter {
    position: absolute;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    font-size: 1em;
    letter-spacing: 10px;
    padding: 3px 0 0 10px;
}

/*底部盒子(右翻页&页码)*/
.swipeRightBlock {
    flex-direction: row;
    justify-content: flex-end;
    position: absolute;
    bottom: 0;
    width: 100%;
    padding: 0 24px;
    opacity: var(--半透明) !important;
}
/*底部の左翻页*/
.swipe_left {
    position: absolute;
    left: 24px;
    opacity: var(--半透明) !important;
    bottom: -5.5px;
}
/*底部の右翻页*/
.swipe_right {
    margin-bottom: -5.5px;
}

/*翻页の左右图标*/
.swipe_left::before {
    content: "≺≺≺";
    font-size: 0.7em;
    font-weight: 300;
}
.swipe_right::before {
    content: "≻≻≻";
    font-size: 0.7em;
    font-weight: 300;
}


/*⋯⋯⋯⋯ ❶.5 气泡头部 ⋯⋯⋯⋯*/


/*〖❶.5.1 User气泡头部〗*/

/*User气泡大小*/
.mes[is_user="true"] {
    zoom: var(--U整体缩放);
    width: var(--U气泡宽度);
    margin-inline: auto !important;
    padding: 0 0.5em !important;
}

/*Userの头像*/
.avatar img {
    box-shadow: none;
    border-radius: var(--全局角) !important;
}
/*User头像向上放大*/
div[is_user="true"] .avatar img {
    transform: scale(var(--U头像大小));
    transform-origin: bottom center;
}

/*User气泡头部网格*/
.mes[is_user="true"] .mesAvatarWrapper {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
}
.mes[is_user="true"] .mesIDDisplay,
.mes[is_user="true"] .tokenCounterDisplay {
    grid-row: 1;
    align-self: end;
    position: relative;
    top: var(--U楼层上下);
    font-weight: 400;
    font-size: 0.7em;
}

/*Userの楼层左*/
.mes[is_user="true"] .mesIDDisplay {
    grid-column: 1;
    justify-self: start;
    left: var(--U楼层左右);
}
/*Userの计数右*/
.mes[is_user="true"] .tokenCounterDisplay {
    grid-column: 3;
    justify-self: end;
    right: var(--U楼层左右);
}


/*〖❶.5.2 Char气泡头部〗*/

/*Charの楼层*/
.mes[is_user="false"] .mesIDDisplay {
    justify-self: center;
    overflow: hidden;
    text-indent: -1.1ch;
    font-size: 1em;
    font-weight: 400;
    margin-top: var(--C楼层上下) !important;
    padding-bottom: 0.5em;
}

/*Charの头像大图*/
.mes[is_user="false"] .mesAvatarWrapper {
    width: 100%;
}
.mes[is_user="false"] .mesAvatarWrapper .avatar {
    border-radius: var(--美化角) var(--美化角) 0 0;
    border: 1px solid var(--边框色);
    width: 100% !important;
    height: var(--C图片高度) !important;
    overflow: hidden;
    mask-image: var(--C图片渐变);
}
.mes[is_user="false"] .mesAvatarWrapper .avatar img {
    border-radius: 0 !important;
    border: none;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    object-position: var(--C图片取景) !important;
    transform: scale(var(--C图片缩放, 1));
    transform-origin: var(--C图片取景);
    filter: var(--C图片灰度);
}
/*禁用头像点击*/
.mesAvatarWrapper {
    pointer-events: none;
}


/*〖❶.5.3 头部姓名时间〗*/

/*姓名*/
.name_text {
    letter-spacing: 3px;
    padding-left: 3px;
    font-size: 1.3em;
}
/*Charの姓名*/
div[is_user="false"] .name_text {
    letter-spacing: 5px;
    padding-left: 5px;
    font-size: 1.8em;
}

/*时间*/
.timestamp {
    position: relative;
    white-space: nowrap;
    letter-spacing: 3px;
    padding-left: 3px;
}
/*Charの时间*/
.mes[is_user="false"] .timestamp {
    letter-spacing: 4px;
    padding-left: 4px;
}

/*时间の左图标*/
.timestamp::before {
    position: absolute;
    content: "‣‣‣‣‣";
    transform: scaleX(-1);
    right: 100%;
    letter-spacing: 3px;
    margin-right: 6px;
}
/*时间の右图标*/
.timestamp::after {
    position: absolute;
    content: "‣‣‣‣‣";
    left: 100%;
    letter-spacing: 3px;
    margin-left: 6px;
}


/*⋯⋯⋯⋯ ❶.6 铅笔设置 ⋯⋯⋯⋯*/


/*〖❶.6.1 铅笔基础〗*/

/*去铅笔の阴影*/
.mes_button,
.mes_edit_buttons {
    filter: none !important;
}
/*铅笔垂直居中*/
.mes_buttons {
    align-items: center;
}

/*文本铅笔大小*/
.mes_buttons > .extraMesButtons,
.mes_buttons > :not(.extraMesButtons) {
    font-size: calc(var(--铅笔大小) * 1.25);
}
/*思考铅笔大小*/
.mes_reasoning_actions {
    font-size: calc(var(--铅笔大小) * 1.05);
    margin-right: 10%;
    padding-top: 10px;
}


/*〖❶.6.2 铅笔图标(美化)〗*/

/*按键拿出来用*/
.extraMesButtons {
    display: flex !important;
    opacity: 1 !important;
}
.extraMesButtons:not([style*="flex"]):not([style*="block"]) .mes_button:not(.mes_copy, .mes_create_branch) {
    display: none !important;
}
.mes_edit,
.mes_copy,
.mes_create_branch,
.extraMesButtonsHint {
    font-size: 0 !important;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

/*铅笔の图标组*/
.mes_edit::after,
.mes_copy::after,
.mes_create_branch::after,
.extraMesButtonsHint::after {
    font-size: var(--铅笔大小);
    padding: 0 2px;
}
/*自定义英文*/
.mes_edit::after {
    content: "EDIT"; /*编辑*/
}
.mes_copy::after {
    content: "COPY"; /*复制*/
}
.mes_create_branch::after {
    content: "BRAN"; /*分支*/
}
.extraMesButtonsHint::after {
    content: "MORE"; /*更多*/
}


/*⋯⋯⋯⋯ ❶.7 气泡文本 ⋯⋯⋯⋯*/


/*〖❶.7.1 分割线(美化)〗*/

/*隐藏全局分割线*/
hr {
    display: none;
    background: transparent !important;
}

/*文本の分割线*/
.mes_text hr,
.mes_reasoning hr {
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: visible;
    height: auto;
    opacity: var(--半透明);
    color: var(--文本色);
    font-size: 1.2em;
    margin: 0.5em 0;
}
.mes_text hr::before,
.mes_reasoning hr::before {
    content: "＊　＊　＊";
}

/*去文本の分割线上下*/
.mes_text p:has(+ hr),
.mes_reasoning p:has(+ hr) {
    margin-bottom: 0 !important;
}
.mes_text hr + p,
.mes_reasoning hr + p {
    margin-top: 0 !important;
}


/*〖❶.7.2 代码块〗*/

code {
    border-radius: var(--全局角);
    background: rgb(from var(--文本色) r g b / 0.1) !important;
    border: none;
    color: var(--文本色) !important;
    font-size: 0.9em;
    margin-inline: 0.25em;
    padding-inline: 0.5em;
}
/*文本の长代码块*/
.mes_text pre,
.mes_reasoning pre {
    text-align: left !important;
    margin: 0.5em 0;
}

/*去文本の代码块上下*/
.mes_text p:has(+ pre),
.mes_reasoning p:has(+ pre) {
    margin-bottom: 0 !important;
}
.mes_text pre + p,
.mes_reasoning pre + p {
    margin-top: 0 !important;
}


/*〖❶.7.3 引用块〗*/

.mes_text blockquote,
.mes_reasoning blockquote {
    border-radius: 0;
    background-color: transparent;
    border-left: 2px solid var(--引用色);
    font-size: 0.95em;
    margin: 0.5em 0 0.5em 1em;
    padding: 0.25em 1em;
}

/*去文本の思维块上下*/
.mes_text p:has(+ blockquote),
.mes_reasoning p:has(+ blockquote) {
    margin-bottom: 0 !important;
}
.mes_text blockquote + p,
.mes_reasoning blockquote + p {
    margin-top: 0 !important;
}




/*┌─────────────────────────┐
  │     《 ❷ 顶 底 栏 》     │
  └─────────────────────────┘*/


/*⋯⋯⋯⋯ ❷.1 顶栏设置 ⋯⋯⋯⋯*/


/*〖❷.1.1 顶栏基础〗*/

/*顶栏高度*/
#top-bar {
    box-shadow: none;
    height: var(--topBarBlockSize);
}

/*顶栏图标*/
.drawer-icon {
    width: auto;
