}
/*左菜单图标打开*/
body:has(#options:not([style*="display: none"])) #options_button::before,
body:has(#extensionsMenu:not([style*="display: none"])) #extensionsMenuButton::before {
    color: var(--次点色);
}
/*故事神谕图标打开*/
body:has(#so-window.so-opening:not([style*="display: none"])) #so-chatbar-button {
    color: var(--次点色);
}
/*Qr助手图标打开*/
