}


/*〖❷.1.4 底栏Qr〗*/

#send_form {
    position: relative !important;
}
#qr--bar {
    position: absolute !important;
    bottom: 100%;
    left: 0;
    padding: 0 !important;
    opacity: 1 !important;
}
#qr--bar .qr--buttons .qr--button.menu_button {
