    border: var(--美化框) solid var(--边框色);
    color: rgb(from var(--文本色) r g b / var(--半透明));
    font-size: 0.95em;
    font-weight: 500;
    margin: 0;
    padding: 0 0.7em;
    height: 2.5em;
}
#qr--bar .qr--buttons .qr--button.menu_button:hover {
    text-shadow: none;
    background: var(--边框色) !important;
    color: var(--文本色);
}


/*〖❷.1.5 底栏本体(基础)〗*/

#send_textarea {
    border: none;
    line-height: 1.5;
}
#dialogue_del_mes {
    margin-top: 1px;
}

#form_sheld {
    border-radius: 0;
    background: var(--背景色);
    border: var(--美化框) solid var(--边框色);
    border-bottom: none;
    box-shadow: 0 800px 0 800px var(--背景色);
}
#form_sheld #send_form {
    backdrop-filter: none;
    outline: none !important;
    background: transparent !important;
    border: none !important;
    padding: var(--美化框) var(--美化框) 0 var(--美化框);
}


/*〖❷.1.6 底栏本体(美化)〗*/

#form_sheld {
    border-radius: 0 0 var(--美化角) var(--美化角);
    background: var(--聊天色);
    border: var(--美化框) solid var(--边框色);
    border-top: none;
}
/*图标左右*/
#nonQRFormItems {
    width: calc(100% - (var(--美化框) * 4));
    margin: 0 auto;
}

/*底栏缎带*/
#send_form {
    position: relative !important;
    bottom: calc(var(--美化框) * -0.5);
}
#qr--bar {
    bottom: calc(100% - (var(--美化框) * 0.5));
}
/*边框*/
#send_form::before {
    position: absolute;
    content: "";
    z-index: -2;
    top: calc(var(--美化框) * -0.5);
    bottom: calc(var(--美化框) * -0.5);
    left: 0;
    right: 0;
    background-color: var(--边框色);
    clip-path: polygon( 0 0, 0.8em 50%, 0 100%, 100% 100%, calc(100% - 0.8em) 50%, 100% 0 );
}
/*底色*/
#send_form::after {
    position: absolute;
    content: "";
    z-index: -1;
    top: calc(var(--美化框) * 0.5);
    bottom: calc(var(--美化框) * 0.5);
    left: calc(var(--美化框) + 0.1em);
    right: calc(var(--美化框) + 0.1em);
    background-color: var(--背景色);
    clip-path: polygon( 0 0, 0.8em 50%, 0 100%, 100% 100%, calc(100% - 0.8em) 50%, 100% 0 );
}

/*底栏输入*/
#send_textarea::placeholder {
    text-shadow: none;
    color: transparent !important;
}
#send_textarea {
    position: relative;
}
/*自定义文字*/
#send_form:has(#send_textarea:placeholder-shown) #rightSendForm::before {
    position: absolute;
    content: "✶";
    pointer-events: none;
    top: calc(50% - 1.8px);
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--边框色);
    opacity: var(--微透明);
    font-size: 0.55em;
}


/*〖❷.1.7 底栏图标(美化)〗*/

/*底栏左菜单图标*/
#options_button::before, #extensionsMenuButton::before {
    position: relative;
    content: var(--底栏图标左1);
    display: inline-block;
    bottom: 0.073em;
}
#extensionsMenuButton::before {
    content: var(--底栏图标左2);
}
/*左菜单打开の图标动画*/
body:has(#options:not([style*="display: none"])) #options_button::before,
body:has(#extensionsMenu:not([style*="display: none"])) #extensionsMenuButton::before {
    transition: transform 0.8s ease;
    transform: rotateY(180deg); 
}

/*底栏右发送&中止图标*/
#send_but::before,
#mes_stop::before {
    position: relative;
    content: var(--底栏图标右);
    display: inline-block;
    bottom: 0.073em;
}
#mes_stop::before {
    bottom: 0.1073em;
}
/*隐藏原生图标*/
:is(#send_but, #mes_stop) i {
    display: none !important;
}
/*生成中の动画*/
#mes_stop::before {
    animation: crow-float 1.8s ease-in-out infinite;
}
@keyframes crow-float {
    50% { transform: translateY(-0.4em); }
}




/*┌─────────────────────────┐
  │     《 ❸ 底 框 域 》     │
  └─────────────────────────┘*/


/*⋯⋯⋯⋯ ❸.1 标题 ⋯⋯⋯⋯*/


/*〖❸.1.1 主标题〗*/

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader:not(.inline-drawer-header):not(.margin0) {
