}

/*按钮间距回调*/
#user-settings-block h4 i,
.standoutHeader i {
    letter-spacing: normal;
}


/*〖❸.1.2 副标题〗*/

/*清除原生文字底框*/
.inline-drawer-header:not(.world_entry .inline-drawer-header),
.standoutHeader ~ .inline-drawer-content {
