}

/*设置整体大框*/
.inline-drawer.wide100p:not(.world_entry .inline-drawer.wide100p),
#completion_prompt_manager_popup .completion_prompt_manager_prompt,
#spoiler_free_desc {
    border-radius: var(--全局角);
    background: rgb(from var(--标题底框色) r g b / calc(alpha - 0.4));
    border: 2px solid var(--标题底框色);
    margin: 3px 0;
    padding: 0 1.5em;
}

/*大框外上下*/
#range_block_openai .inline-drawer.m-t-1.wide100p {
    margin-top: 1em;
}
#range_block_openai .inline-drawer.wide100p:not(.m-t-1) {
    margin-bottom: 8px;
}
#wiTopBlock .inline-drawer.wide100p.flexFlowColumn {
    margin-top: 0;
}
#UI-Theme-Block .inline-drawer.wide100p.flexFlowColumn {
    margin: 0 0 8px 0;
}

/*展开内容上下*/
.inline-drawer-content,
.standoutHeader ~ .inline-drawer-content {
    padding: 0.5em 0 calc(0.5em + 3.5px) !important;
}

/*世界书「额外匹配来源」*/
.userSettingsInnerExpandable {
    border: none;
    margin: 0;
    padding: 3.5px 0 !important;
}
.world_entry_edit .inline-drawer.wide100p {
    border-radius: var(--全局角);
    border: 2px solid var(--标题底框色) !important;
    width: 95%;
    margin: 3px 2.5%;
    padding-inline: 1.5em;
}


/*⋯⋯⋯⋯ ❸.2 文本域 ⋯⋯⋯⋯*/


/*〖❸.2.1 聚焦边〗*/

textarea:not(#send_textarea):not(.select2-search__field):focus,
.text_pole:focus,
input:not([type="range"]):not([type="checkbox"]):not([type="radio"]):not([type="color"]):not([type="file"]):not(.bai-bai-floor-input):focus,
select:focus,
.select2-container--focus .select2-selection {
    outline-offset: -2px !important;
    outline: 2px solid var(--聚焦边框色) !important;
    border-color: transparent !important;
    box-shadow: none !important;
}


/*〖❸.2.2 文本域〗*/

/*基础文本域*/
textarea:not(#send_textarea):not(.select2-container .select2-search--inline textarea.select2-search__field),
.text_pole:not(select):not(input[type="number"]),
input.select2-search__field {
    border-radius: var(--全局角);
    background-color: var(--文本域底色);
    border: 1px solid var(--自定义框色) !important;
    padding: 0.5em;
    padding-left: calc(0.5em + var(--滚动条宽)) !important;
    scrollbar-gutter: stable;
}
input.text_pole {
    padding: 3px 0 !important;
}

/*拖动长短の手柄*/
textarea::-webkit-resizer {
    border-radius: var(--全局角);
    background: var(--滚动条色);
}
/*隐藏底栏输入の手柄*/
#send_textarea {
    resize: none;
}

/*数字文本域*/
input[type="number"] {
    border-radius: var(--全局角);
    background-color: var(--文本域底色);
    border: 1px solid var(--自定义框色) !important;
    text-align: center; /*字居中*/
    padding-inline: 2px;
}
/*隐藏数字调整*/
input[type="number"]::-webkit-inner-spin-button {
    -webkit-appearance: none;
}


/*⋯⋯⋯⋯ ❸.3 选择器 ⋯⋯⋯⋯*/


/*〖❸.3.0 选择器基础〗*/

/*选择器底框*/
select,
.select2-selection {
    border-radius: var(--全局角) !important;
    background-color: var(--选择器底色) !important;
    border: 1px solid var(--自定义框色) !important;
    color: var(--选择器字色) !important;
    text-align: center; /*字居中*/
    padding-inline: 3px !important;
    background-image: none; /*隐藏▽*/
}

/*选择器常用*/
#settings_preset_openai,
#connection_profiles,
#world_editor_select,
#themes {
    background-color: rgb(from var(--选择器底色) r g b / calc(alpha + 0.4)) !important;
    color: rgb(from var(--选择器字色) r g b / calc(alpha + 0.4)) !important;
}


/*〖❸.3.1 选择器-壹〗*/

/*手机の选择器1展开*/
select option {
    border-radius: var(--全局角);
    margin: 3px 0 3px var(--滚动条宽);
    scrollbar-gutter: stable;
    padding: 2px;
}
/*未选*/
select option:not(:checked) {
    background-color: transparent;
    color: var(--选择器字色);
}
/*选中*/
select option:checked {
    box-shadow: 0 0 100px 100px rgb(from var(--边框色) r g b / calc(alpha + 0.4)) inset; /*底*/
    -webkit-text-fill-color: rgb(from var(--选择器字色) r g b / calc(alpha + 0.4)); /*字*/
    font-weight: 600;
}

/*电脑の选择器1展开*/
@media (min-width: 1001px) {
  /*未选*/
    select option:not(:checked) {
        background-color: var(--背景色);
    }
  /*选中*/
    select option:checked {
        background-color: var(--边框色);
    }
}


/*〖❸.3.2 选择器-贰〗*/

/*电脑の选择器2当前世界书*/
.select2-container .select2-selection--single {
    background-color: rgb(from var(--选择器底色) r g b / calc(alpha + 0.4)) !important;
    border: 1px solid var(--自定义框色) !important;
    color: rgb(from var(--选择器字色) r g b / calc(alpha + 0.4)) !important;
}

/*电脑の选择器2全局世界书*/
@media (min-width: 1001px) {
  /*整体*/
    .select2-container--default .select2-selection--multiple {
        scrollbar-width: none;
        text-align: left; /*靠左*/
        padding: 0 0.5em 5px 0.5em !important;
    }

  /*胶囊*/
    .select2-container--default .select2-selection--multiple .select2-selection__choice {
        display: inline-flex; /*对齐*/
        border-radius: var(--全局角);
        background-color: var(--边框色);
    }
    /*左叉叉*/
    span.select2.select2-container .select2-selection__choice__remove {
        background-color: transparent;
        padding: 0 6px;
        line-height: 1.36;
    }
    /*右名称*/
    span.select2.select2-container .select2-selection__choice__display {
        background-color: transparent;
        margin-right: 0;
        padding: 0 0.5em;
        line-height: 1.5;
        text-align: justify; /*字对齐*/
    }

  /*展开*/
    .select2-container--default.select2-container--open .select2-dropdown {
        box-shadow: none;
        border-radius: var(--全局角);
        border: 1px solid var(--自定义框色) !important;
        padding: 0.5em 0.2em 0.5em 1em;
    }
    /*未选*/
    .select2-results__option::before {
        border-radius: var(--全局角);
    }
    /*选中*/
    .select2-results__option--selected.select2-results__option::before {
        content: "";
        border: 1px solid var(--勾选图标色);
        background: var(--勾选图标色);
    }
}


