}


/*〖❸.4.4 收起&展开按钮〗*/

.inline-drawer-icon {
    position: relative;
    margin-left: 0.5em;
}
.inline-drawer-icon,
.inline-drawer-icon::before,
.inline-drawer-icon::after {
    filter: none;
    text-shadow: none;
}

/*全局收起按钮*/
.inline-drawer-icon:not(#logprobsViewer *):not(.world_entry_thin_controls *):is(.down, .fa-circle-chevron-down)::before {
    position: absolute;
    content: var(--收起图标);
    font-size: 1.2em;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--收起图标色);
}

/*全局展开按钮*/
.inline-drawer-icon:not(#logprobsViewer *):not(.world_entry_thin_controls *):not(.down):not(.fa-circle-chevron-down)::before {
    position: absolute;
    content: var(--展开图标);
    font-size: 1.2em;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--展开图标色);
}


/*〖❸.4.5 勾选框〗*/

/*勾选文字栏*/
.checkbox_label,
#qr--settings .flex-container {
    align-items: center !important;
}
.checkbox_label:not(.flex1),
#WorldInfo .checkbox_label,
#qr--settings .flex-container {
    align-items: center !important;

}

/*「自动解析」勾选文本*/
div.flex-container.alignItemsBaseline:has(label[for="reasoning_auto_parse"]) {
    align-items: center !important;
    gap: 0;
    margin: 0.75em 0 0.25em 0;
}

/*勾选框*/
input[type="checkbox"] {
    filter: none;
    box-shadow: none;
    outline: none;
    overflow: visible; /*允许溢出*/
    transform: translateY(0px);
    border-radius: var(--全局角);
    border: none;
    background-color: var(--勾选框底色);
    height: 1em;
    width: 1em;
    margin: 0.4em;
}
/*删除消息气泡の勾选*/
input[type='checkbox'].del_checkbox {
    margin: 1em 0 0.5em 0;
}

/*已选の底&勾*/
input[type="checkbox"]:checked {
    background-color: var(--勾选图标色);
}
input[type="checkbox"]::before {
    box-shadow: inset 1em 1em var(--勾选图标色);
}

/*勾选美化*/
input[type="checkbox"]:checked {
    background-color: transparent;
}
input[type="checkbox"]::before {
    display: none;
}
input[type="checkbox"]:checked::after {
    content: var(--勾选图标);
    padding-bottom: var(--勾选图标上下);
    color: var(--勾选图标色);
    font-size: var(--勾选图标大小);
    font-weight: 800;
}


/*〖❸.4.6 滑动条〗*/

/*轨道*/
input[type="range"] {
    filter: none !important;
    box-shadow: none !important;
    border-radius: var(--全局角) !important;
    background: transparent !important;
    overflow: hidden; /*截断底色*/
    height: 0.45em !important;
    max-width: 90%;
    margin-inline: 5%;
}

/*滑块*/
input[type="range"]::-webkit-slider-thumb {
    border-radius: var(--全局角) !important;
    border: none;
    box-shadow: -100vw 0 0 calc(100vw - 1em) var(--滑条轨道色); /*底*/
    background: var(--滑条滑块色); /*滑块*/
    height: 0.5em;
    width: 1.2em;
}
/*滑块操作变色*/
input[type="range"]::-webkit-slider-thumb:hover {
    background-color: var(--重点色);
}




/*┌─────────────────────────┐
  │     《 ❹ 初 始 化 》     │
  └─────────────────────────┘*/


/*⋯⋯⋯⋯ ❹.1 酒馆启动 ⋯⋯⋯⋯*/


/*隐藏「Logo」「加载中…」*/
.splash-logo,
.splash-message {
    display: none;
}

/*加载图标（原齿轮）*/
#load-spinner {
    animation: none;
}
#load-spinner::before {
    content: "✶";
    color: var(--重点色);
    font-size: 1em;
    animation: star-flip 3s linear infinite;
}
@keyframes star-flip {
    0% { transform: perspective(400px) rotateY(0); }
    100% { transform: perspective(400px) rotateY(360deg); }
}

/*去加载遮罩*/
.popup[open]:has(.splash-message)::backdrop {
    background-color: transparent;
}


/*⋯⋯⋯⋯ ❹.2 界面基础 ⋯⋯⋯⋯*/


/*竖向无缝*/
#sheld {
    min-height: calc(100dvh - var(--topBarBlockSize));
}
#form_sheld {
    margin-top: 0;
}

/*横向无缝*/
#left-nav-panel,
#right-nav-panel {
    width: calc((100vw - var(--sheldWidth)) / 2 - 0px);
}

/*侧栏触底*/
#left-nav-panel,
#right-nav-panel {
    max-height: 100dvh;
    border-radius: 0;
    border: none;
}
/*(手机)*/
@media (max-width: 1000px) {
    .fillLeft .scrollableInner {
        max-height: 100dvh;
    }
    #left-nav-panel,
    #right-nav-panel {
        height: calc(100dvh - var(--topBarBlockSize)) !important;
    }
}

/*抽屉触底*/
.drawer-content {
    max-height: calc(100dvh - var(--topBarBlockSize));
    border-radius: 0 0 var(--全局角) var(--全局角);
    border: none;
    border-bottom: var(--美化框) solid var(--边框色);
}

/*弹窗触底(手机)*/
@media (max-width: 1000px) {
    .wide_dialogue_popup {
        min-width: 100dvw;
        min-height: 100dvh;
    }

/*酒馆助手「编辑脚本」&「脚本库」弹窗*/
    .vfm__content > .popup:has(.TH-script-editor-container),
    .vfm__content > .popup:has(h3):has(.fa-plus) {
        min-width: 100dvw;
        min-height: 100dvh;
}

  /*提示词の查看弹窗*/
    #completion_prompt_manager_popup:has(#completion_prompt_manager_popup_inspect[style*="display: flex"]) {
        height: auto;
        min-height: 0;
    }
  /*提示词の编辑弹窗*/
    #completion_prompt_manager_popup:not(:has(#completion_prompt_manager_popup_inspect[style*="display: flex"])) {
        top: 0;
        min-height: 100dvh;
        max-height: 100vh;
    }

  /*酒馆助手大编辑窗口*/
    .popup [class*="max-h-[80vh]"],
.popup:not(:has(.img_enlarged_container)) .popup-body {
        max-height: 100dvh;
    }
}




/*⋯⋯⋯⋯ ❹.3 界面居中 ⋯⋯⋯⋯*/


/*〖❹.3.1 滚动条〗*/

::-webkit-scrollbar {
    width: var(--滚动条宽);
}
::-webkit-scrollbar:horizontal {
    height: var(--滚动条宽);
}

/*滚动条轨道*/
::-webkit-scrollbar-track:hover {
    background: transparent;
}

/*滚动条滑块*/
::-webkit-scrollbar-thumb {
    box-shadow: none !important;
    border-radius: var(--全局角) !important;
    background-color: var(--滚动条色) !important;
}
::-webkit-scrollbar-thumb:hover {
    background-color: var(--重点色) !important;
}


/*〖❹.3.2 页面居中〗*/

/*页面初始化*/
#left-nav-panel,
.range-block.m-b-1,
#wi-holder,
#Backgrounds,
#right-nav-panel {
    margin: 0;
    padding: 0;
}

/*页面活动边距*/
.fillLeft .scrollableInner,
.drawer-content:not(#left-nav-panel):not(#Backgrounds):not(#right-nav-panel):not(#movingDivs>.drawer-content),
#bg-scrollable-content,
#rm_print_characters_block,
#form_create {
    padding: 1em;
