}
#bg-scrollable-content {
    padding-top: 0;
}

/*聊天页边距*/
#chat {
    padding-top: var(--滚动条宽);
    padding-left: var(--滚动条宽);
    scrollbar-gutter: stable;
}

/*页面固定边距*/
#bg-header-fixed,
#CharListButtonAndHotSwaps,
#rm_PinAndTabs,
#charListFixedTop,
#rm_print_characters_pagination {
    padding: 0 calc(var(--界面边距) + var(--滚动条宽));
    padding-top: 1em;
}
#bg_tabs .bg_tabs_list {
    margin: 0 calc(var(--界面边距) + var(--滚动条宽));
}

/*电脑の右侧栏头部*/
@media (min-width: 1001px) {
    #CharListButtonAndHotSwaps {
        padding: 0;
        padding-bottom: 1em;
    }
}

/*干掉阴影闪烁*/
.recentChat,
.world_entry,
.character_select {
    box-shadow: none !important;
}
.recentChat {
    animation: none !important;
}


/*〖❹.3.3 大量弹窗〗*/

.popup {
    border-radius: var(--全局角) !important;
    box-shadow: none;
}

/*提示词の查看弹窗内滚动*/
#completion_prompt_manager_popup_entry_form_inspect_list .inline-drawer-content {
    max-height: 65vh;
    overflow-y: auto;
    width: auto;
    margin: 0 -0.5em;
    padding-left: calc(0.5em + var(--滚动条宽)) !important;
    padding-right: 0.5em !important;
    scrollbar-gutter: stable !important;
    text-align: justify;
}
.TH-popup .popup:has(textarea.text_pole[class*="h-dvh"]) > div.h-full {
  display: flex;
  flex-direction: column;
}


/*宽弹窗*/
.wide_dialogue_popup {
    padding: 1.5em 0.5em 0.5em 0.5em !important;
}
.wide_dialogue_popup .popup-content {
    margin: 0;
    padding: 0 1em 0 1em;
}
.wide_dialogue_popup .popup-content {
    border-radius: var(--全局角) var(--全局角) 0 0 !important;
}

/*带滚动条の宽弹窗*/
.popup.vertical_scrolling_dialogue_popup .popup-content {
    padding-left: calc(0.5em + var(--滚动条宽));
    padding-right: 0.5em;
    scrollbar-gutter: stable;
}

/*作者注释等菜单弹窗*/
/*外框*/
#floatingPrompt,
#cfgConfig,
#logprobsViewer,
#movingDivs > div {
    box-shadow: none;
    border-radius: var(--全局角);
    padding: 0;
}
