}
.floating_panel_close, .floating_panel_maximize {
    margin-right: 0.3em;
}

/*作者注释 CFG缩放*/
#floatingPrompt .inline-drawer,
#cfgConfig .inline-drawer {
    border-radius: var(--全局角);
    background: rgb(from var(--标题底框色) r g b / calc(alpha - 0.4));
