}
#floatingPrompt .inline-drawer-icon,
#cfgConfig .inline-drawer-icon {
    margin-right: 0.5em;
}

/*Token概率*/
#logprobsViewer {
    padding: 1em !important;
}
#logprobs_selected_top_logprobs {
    border-color: var(--边框色);
}

/*图库*/
#gallery {
    padding: 1.5em !important;
}

/*数据库*/
dialog[open]:has(.dataBankAttachments),
.popup .popper-modal {
    box-shadow: none !important;
    padding: 0.5em !important;
    border-radius: var(--全局角) !important;
}

/*「管理聊天文件」弹窗*/
#select_chat_popup {
    box-shadow: none !important;
    border-radius: var(--全局角);
    padding: 1em !important;
    min-height: 50dvh;
}
/*文件*/
.select_chat_block, .swipe_picker_block {
    border-radius: var(--全局角);
    padding: 6px 4px 6px 10px;
}
#select_chat_search {
    min-width: 30%;
