}
#select_chat_cross {
    margin-left: 5px;
    margin-bottom: 5px;
}

/*酒馆助手脚本弹窗边距*/
@layer my-override {
    .popup.box-border[role="dialog"] {
        padding: 1em 0em 0 0em !important;
    }
}
div[class="h-full max-h-[80vh] overflow-y-auto"] {
    padding-left: calc(1em + var(--滚动条宽));
    padding-right: 1em;
    scrollbar-gutter: stable;
}
.vfm__content .popup.box-border{
    width: 100vw;
    min-width: 100dvw;
    max-width: none !important;
    min-height: 100dvh;
}


/*酒馆助手脚本弹窗文本高*/
/*收起*/
.TH-script-editor-container .text_pole.relative.w-full.overflow-hidden {
    min-height: 20vh !important;
}
/*展开*/
textarea[placeholder*="脚本的"] {
    min-height: 30vh !important;
}
/*去「展开编辑」底色*/
.TH-script-editor-container [class*="to-transparent"] {
    background: none !important;
}
/*展开编辑*/
.TH-script-editor-container [class*="to-transparent"] button {
