    padding: 0.5em 1em;
}




/*┌─────────────────────────┐
  │     《 ❺ 全 界 面 》     │
  └─────────────────────────┘*/


/*⋯⋯⋯⋯ ❺.⓪ 欢迎页₀ ⋯⋯⋯⋯*/


/*〖❺.⓪.1 欢迎页头部〗*/

/*大底板*/
.welcomePanel {
    background: transparent !important;
    border: none !important;
    margin-bottom: 1em !important;
    padding: 0;
}

/*头部盒子*/
.welcomeHeaderTitle {
    position: relative;
    display: flex;
    align-items: center;
    margin: 0.5em 0 1em 0 !important;
}

/*隐藏logo*/
.welcomeHeaderLogo {
    display: none;
}

/*版本号*/
.welcomeHeaderVersionDisplay {
    /*display: none; /*隐藏*/
    position: absolute;
top:0;
    left: 50%;
    transform: translateX(-50%);
    white-space: nowrap;
    opacity: var(--深透明);
    font-size: 0.8em !important;
    font-weight: 400 !important;
}

/*齿轮左*/
.recentChatsSettings {
    position: absolute;
    left: 2em;
    top: 1.7em;
}
/*收起右*/
.showRecentChats,
.hideRecentChats {
    position: absolute;
    right: 2em;
    top: 1.7em;
}

/*「最近の聊天」*/
.welcomeHeader {
    display: flex;
    flex-direction: column !important;
    align-items: center;
}
/*第一排 社区指引*/
.welcomeShortcuts {
    order: 1;
    opacity: var(--半透明);
}
/*第二排 标题文字*/
.recentChatsTitle {
    order: 2;
}


/*〖❺.⓪.2 最近聊天列表〗*/

/*选择某个聊天*/
.welcomeRecent .recentChatList .recentChat {
    border-radius: var(--全局角);
}
.welcomeRecent .recentChatList .recentChat:hover {
    background-color: transparent;
    outline: 2px solid var(--次点色);
    outline-offset: -2px;
}

/*隐藏左置顶图钉*/
.recentChatPinned {
    display: none;
}
/*右图钉按钮变色*/
.recentChat:has(.recentChatPinned) .chatActions .fa-thumbtack {
    color: var(--重点色);
}

/*置顶聊天底色*/
.recentChat:has(.recentChatPinned) {
    background-color: var(--开启条目色);
}
/*补充点击时候的底色*/
.welcomeRecent .recentChatList .recentChat:has(.recentChatPinned):hover {
    background-color: var(--开启条目色);
}

/*聊天名网格*/
.chatNameContainer {
    display: grid !important;
    grid-template-columns: 1fr auto auto;
    grid-template-areas:
        "name date actions"
        "file file file";
    gap: 0 5px !important;
    align-items: baseline;
}
.chatName {
    display: contents;
}

/*第一排 角色名*/
.characterName {
    grid-area: name;
    opacity: var(--半透明);
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
}
.characterName::before {
    content: "® ";
    font-size: 1rem;
    opacity: var(--半透明);
}
/*隐藏「–」*/
.chatName span:nth-of-type(1) {
    display: none;
}

/*第一排 日期*/
.chatDate {
    grid-area: date;
}

/*第一排 操作按钮*/
.chatActions {
    grid-area: actions;
}
.welcomeRecent .recentChatList .recentChat .chatActions {
    gap: 0;
}

/*第二排 文件名*/
.chatName span:nth-of-type(2) {
    grid-area: file;
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
}

/*预览文本*/
body.big-avatars .welcomeRecent .recentChatList .recentChat .chatMessageContainer .chatMessage {
    opacity: var(--半透明);
    -webkit-line-clamp: 3;
    line-clamp: 3;
}
.welcomeRecent .recentChatList .recentChat .chatMessageContainer .chatMessage {
    opacity: var(--半透明);
    -webkit-line-clamp: 2;
    line-clamp: 2;
}

/*统计*/
.chatStats {
    flex-direction: column !important;
    align-items: flex-end !important;
}


/*⋯⋯⋯⋯ ❺.① 对话预设₁ ⋯⋯⋯⋯*/


/*〖❺.①.1 预设大标题〗*/

#ai_response_configuration .title_restorable {
    flex-direction: column-reverse;
    background: transparent;
    border: none;
    padding: 0;
    margin-bottom: 1em;
    gap: 5px;
}

/*第一行の按钮*/
#ai_response_configuration .title_restorable > div.flex-container {
    gap: 5px !important;
    opacity: var(--微透明);
    margin: 5px 0;
}

/*第二行の标题文字*/
#ai_response_configuration .title_restorable > strong {
    font-size: 1.3em;
}
/*左图标*//*
#ai_response_configuration .title_restorable > strong::before {
    content: "〈";
    color: var(--次点色);
}
/*右图标*//*
#ai_response_configuration .title_restorable > strong::after {
    content: "〉";
    color: var(--次点色);
}

/*隐藏"单击滑块以手动输入值"*/
#clickSlidersTips {
    display: none !important;
}

/*「角色名称」&「继续后缀」*/
.inline-drawer-header:has(#character_names_display, #continue_postfix_display) .flex-container {
    width: 100%;
}
.inline-drawer-header:has(#character_names_display, #continue_postfix_display) .flexBasis100p {
    flex-basis: auto;
    margin-left: auto;
    margin-right: 1.5em;
}


/*〖❺.①.2 提示词条目区〗*/

/*「提示词」三个字*/
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}
/*补色*/
#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--文本色) !important;
}

/*管理底板*/
#completion_prompt_manager_list {
    background: transparent;
    border: none !important;
    padding: 0 0.5em !important;
}

/*提示词条目*/
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    padding: 0.5em 1em !important;
}
/*手机(带拖动≡)*/
@media (max-width: 1000px) {
    #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
        padding: 0.5em 0.8em 0.5em 2em !important;
    }
    #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .drag-handle {
        padding: 0 0.8em !important;
    }
}

/*开启の条目*/
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    border-radius: var(--全局角);
    background-color: rgb(from var(--开启条目色) r g b / calc(alpha + 0));
    border: 1px solid rgb(from var(--开启条目色) r g b / calc(alpha + 0)) !important;
}
/*开启条目の名称*/
li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .completion_prompt_manager_prompt_name a {
    font-weight: 500;
}

/*关闭の条目*/
.completion_prompt_manager_prompt_disabled {
    border: 1px solid transparent !important;
    opacity: var(--半透明);
}
/*关闭条目の名称补色*/
.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name a {
    color: var(--文本色) !important;
}

/*星星图标の条目名称*/
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:has(.fa-star) .completion_prompt_manager_prompt_name a {
    font-weight: 900;
}

/*条目左小图标*/
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    position: relative;
    bottom: 1px;
    color: rgb(from var(--文本色) r g b / var(--微透明));
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-star {
    color: var(--文本色) !important;
}

/*条目名称强制单行(重置)*/
html body #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name {
    display: block !important;
    white-space: nowrap !important;
}

/*条目右编辑键*/
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
    filter: none;
    opacity: var(--半透明);
}
/*⛓*/
#completion_prompt_manager .caution {
    color: var(--重点色);
}


/*〖❺.①.3 提示词查看弹窗〗*/

/*初始化(查看＆编辑)*/
#completion_prompt_manager_popup {
