/*〖❺.④.5 条目展开内部(手机)〗*/

@media (max-width: 1000px) {

  /*关键词 & 过滤器*/
    .keyprimarytextpole,
    .keysecondarytextpole {
        overflow: hidden !important;
        field-sizing: content;
        height: auto !important;
        min-height: calc(1.4em * 2 + 10px) !important;
    }
    /*框为空时*/
    .keyprimarytextpole:placeholder-shown,
    .keysecondarytextpole:placeholder-shown {
        max-height: calc(1.4em * 2 + 10px) !important;
    }

  /*六个框两行*/
    [name="perEntryOverridesBlock"] > .world_entry_form_control {
        flex: 1 1 calc(33.33% - 10px);
    }
    [name="perEntryOverridesBlock"] > .world_entry_form_control:nth-child(1) {
        order: 4;
    }
    [name="perEntryOverridesBlock"] > .world_entry_form_control:nth-child(5) {
        order: 5;
    }
    [name="perEntryOverridesBlock"] > .world_entry_form_control:nth-child(6) {
        order: 6;
    }

  /*递归勾选两行*/
    [name="contentAndCharFilterBlock"] label > small > span.justifySpaceBetween {
        display: grid;
    }
    [name="contentAndCharFilterBlock"] label > small > span.justifySpaceBetween > .flex-container:nth-child(3) {
        grid-column: 1 / 3;
        padding: 5px;
    }
    [name="contentAndCharFilterBlock"] label > small > span.justifySpaceBetween > .flex-container:nth-child(3) > .flexFlowColumn:first-child {
        max-width: 60%;
    }
    [name="contentAndCharFilterBlock"] label > small > span.justifySpaceBetween > .flex-container:nth-child(3) > .flexFlowColumn:last-child {
        max-width: calc(40% - 5px);
    }
    /*文字溢出省略*/
    [name="contentAndCharFilterBlock"] .checkbox span {
        flex: 1;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

  /*展开 & 词符UID 一排*/
    [name="contentAndCharFilterBlock"] label > small > span.justifySpaceBetween > span:nth-child(2) {
        grid-row: 2;
        padding: 0 0 2px 10px;
    }

    [name="contentAndCharFilterBlock"] label > small > span.justifySpaceBetween > span:nth-child(1) {
        grid-column: 2 / 3;
        grid-row: 2;
        justify-content: flex-end;
        padding-right: 5px;
    }

  /*包含组四小框*/
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) {
        display: grid;
        gap: 0 8px;
    }
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div {
        display: contents;
    }

    /*第一行包含组*/
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div:nth-child(1) > div:nth-child(1) {
        grid-column: 1 / 5;
        align-items: center;
        padding: 0 0 0 5px;
    }
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div:nth-child(1) > div:nth-child(2) {
        grid-column: 1 / 5;
        margin-bottom: 5px;
    }

    /*第二行四个框*/
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) .marginBot5 {
        margin-bottom: 2px !important;
        padding-left: 5px;
    }
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div:nth-child(2) > div:nth-child(2) {
        grid-row: 4;
    }
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div:nth-child(5) > div:nth-child(1) {
        grid-row: 3;
    }
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div:nth-child(3) > div:nth-child(2) {
        grid-row: 4;
    }

  /*绑定到 & 筛选生成*/
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) {
        display: grid;
        gap: 0 10px;
    }
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) > div {
        display: contents;
    }

    /*左边 绑定到角色或标签*/
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) > div:nth-child(1) > div.justifySpaceBetween {
        align-items: center;
        min-width: 50%;
        padding-left: 5px;
    }

    /*右边 筛选生成触发器*/
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) > div:nth-child(2) > div.justifySpaceBetween {
        grid-column: 2 / 3;
        align-items: center;
        justify-content: flex-end;
    }
    /*文字溢出省略*/
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) > div:nth-child(1) > div.justifySpaceBetween > small[for="characterFilter"] {
        flex: 1;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    /*框对齐一行*/
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) > div:nth-child(1) > div.range-block-range {
        grid-row: 2;
    }
}

/*电脑の布局补丁*/
@media (min-width: 1001px) {
  /*展开 & 递归*/
    [name="contentAndCharFilterBlock"] label > small > span {
        padding: 0 8px 3px 5px;
    }
  /*包含组*/
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) {
        align-items: center;
    }
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div:nth-child(1) > div:nth-child(1) {
        align-items: center;
        padding: 0px 5px 5px 5px;
    }
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) > div:nth-child(1) > div:nth-child(1) > label.checkbox_label {
    margin: 0 0 0px 0 !important;
}
    div.flex-container.wide100p.flexGap10:has(input[name="group"]) .marginBot5 {
        padding-left: 5px;
    }

  /*绑定到 & 筛选生成*/
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) > div:nth-child(1) > div.justifySpaceBetween {
        align-items: center;
        padding-left: 5px;
    }
    div.flex-container.wide100p.flexGap10:has(select[name="characterFilter"]) > div:nth-child(2) > div.justifySpaceBetween {
        align-items: center;
        padding-left: 5px;
    }
}

/*通用の布局补丁*/
/*条目名称*/
.world_entry .WIEntryTitleAndStatus > .flex-container.flex1 textarea  {
    resize: none !important;
    padding: 4.5px 0 !important;
}
/*内容对齐*/
.mdhotkey_location {
    line-height: 1;
}
/*正文框居中*/
[name="contentAndCharFilterBlock"] textarea[name="content"] {
    width: calc(100% + 5px);
}
/*额外匹配来源选项两排*/
.world_entry_edit .inline-drawer-header:has(strong[data-i18n="Additional Matching Sources"])
    + .inline-drawer-content:not([style*="display: none"]) {
    display: grid !important;
    grid-template-columns: 1fr 1fr;
}


/*⋯⋯⋯⋯ ❺.⑤ UI主题₅ ⋯⋯⋯⋯*/


/*〖❺.⑤.1 UI主题标题〗*/

/*大标题「用户设置」*/
div[name="userSettingsRowOne"] {
    display: grid !important;
    grid-template-areas:
        "lang version"
        "title title";
    margin-bottom: 1em;
}

/*第一行 语言 & 版本号*/
#UI-language-block {
    grid-area: lang;
    justify-content: flex-start;
    flex-wrap: nowrap !important;
    white-space: nowrap !important;
    gap: 0;
}
#version_display {
    text-align: right;
    opacity: var(--半透明);
}
/*语言选择框*/
#ui_language_select {
    flex: none !important;
    width: 8em !important;
}

/*第二行 标题*/
div[name="userSettingsRowOne"] > div.flex-container {
    grid-area: title;
    justify-content: center;
}
div[name="userSettingsRowOne"] h3 {
    font-size: 1.3em;
}
/*问号*/
div[name="userSettingsRowOne"] .notes-link {
    position: absolute;
    right: 0;
}


/*〖❺.⑤.2 UI主题界面调整〗*/

#user-settings-block-content {
    gap: 0 1em;
}
div[name="FontBlurChatWidthBlock"],
#power-user-option-checkboxes > div:nth-child(1) > div:nth-child(2) {
    gap: 5px 10px;
}
#toastr_position,
div[name="FontBlurChatWidthBlock"],
.flex-container.flexFlowColumn:has(#chat_truncation) {
    margin-bottom: 8px;
}
div:has(> #aux_field) {
    margin: 5px 0;
}

/*左右边距*/
#UI-Theme-Block,
#UI-Customization,
#power-user-options-block {
    padding: 0 5px 0 5px;
}
#user-settings-block h4 {
    margin-left: -5px;
    margin-right: -5px;
}

/*可移动UI预设保存按钮*/
#movingui-preset-save-button{
    margin-bottom: 2px;
}


/*⋯⋯⋯⋯ ❺.⑥ 系统背景₆ ⋯⋯⋯⋯*/


/*〖❺.⑥.1 背景大标题〗*/

.bg-header-row-1 {
    display: flex;
    flex-wrap: wrap;
}
/*占位*/
.bg-header-row-1 .expander {
    display: none !important;
}

/*第一行*/
#background_fitting {
    margin-right: auto;
}
/*第一行 后两个*/
.bg-header-row-1 .menu_button {
    opacity: var(--半透明);
}

/*第二行 标题*/
.bg-header-row-1 h3 {
    width: 100%;
    font-size: 1.3em;
    order: 2;
    display: flex;
    justify-content: center;
}

/*低版本酒馆の大标题*/
.heading-container-with-controls .heading-text {
    font-size: 1.3em;
}
.heading-container-with-controls {
    margin-bottom: calc(1em + 5px);
}


/*〖❺.⑥.2 背景图库〗*/

#bg-header-fixed,
#bg_tabs,
#bg_global_tab {
    box-shadow: none;
    border: none !important;
}

.bg_example {
    box-shadow: none;
    box-sizing: border-box;
    border-radius: var(--全局角);
    border: 1px solid transparent;
    outline: 1px solid var(--边框色);
    outline-offset: -1px; 
    margin: 2px;
}

/*当前背景图聚焦*/
.bg_example.selected-background  {
    outline: 0.35em solid var(--重点色);
    outline-offset: -1px; 
}

/*当前背景图图案*/
.bg_example.selected-background::before {
    position: absolute;
    content: "ᗜ𖥦ᗜ";
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    filter: drop-shadow(0 0 1px #000000);
    color: #ffffff;
    font-size: 2em;
}

/*图片内名称*/
.bg_example .BGSampleTitle {
    color: #ffffff;
    font-weight: 400;
}

/*图片内操作按钮*/
.bg_example .mobile-only-menu-toggle ,
.bg_example .jg-button{
    border-radius: var(--全局角);
}
.bg_example .jg-menu {
    border-radius: var(--全局角);
    border: none;
    right: auto;
    left: 50%;
    transform: translateX(-50%) !important;
}


/*⋯⋯⋯⋯ ❺.⑦ 扩展插件₇ ⋯⋯⋯⋯*/


/*〖❺.⑦.1 扩展标题〗*/

/*页面*/
#rm_extensions_block > div {
    gap: 0 1em;
}
/*未连接*/
#rm_extensions_block > div > div.alignitemscenter.flex-container.justifyCenter.wide100p {
    margin-top: 1em;
}

/*大标题「扩展」*/
div.flex-container:has(> #extensions_details) {
    flex-wrap: wrap;
    justify-content: center;
    margin-bottom: 1em;
}

/*第一行 按钮*/
div.flex-container:has(> #extensions_details) > label,
#extensions_details,
#third_party_extension_button {
    order: 1;
    opacity: var(--半透明);
    flex: 1 1 0px !important;
    white-space: nowrap;
    overflow: hidden;
}
/*加省略号*/
div.flex-container:has(> #extensions_details) > label span,
#extensions_details span,
#third_party_extension_button span {
    overflow: hidden;
    text-overflow: ellipsis;
}
/*左「在扩展更新时通知」限宽*/
div.flex-container:has(> #extensions_details) > label {
    min-width: 11em !important;
}
/*右「管理扩展」「更新扩展」限宽*/
#extensions_details,
#third_party_extension_button {
    min-width: 2em !important;
    max-width: 8em !important;
}

/*第二行 标题文字*/
div.flex-container:has(> #extensions_details) h3 {
    flex: 0 0 100% !important;
    order: 2;
    display: flex;
    justify-content: center;
    font-size: 1.3em;
}

/*扩展标题の展开区*/
#extensions_settings .inline-drawer-content,
#extensions_settings2 .inline-drawer-content {
     padding-inline: 0.5em !important;
}


/*〖❺.⑦.2 扩展管理弹窗〗*/

/*头部*/
.extensions_toolbar {
    padding: 0;
}
.extensions_toolbar button {
    gap: 0;
    font-size: 0.9em;
    margin-top: 0;
}

/*开启插件*/
.extensions_info .extension_block {
    border-radius: var(--全局角);
    background: var(--开启条目色);
    border: 2px solid rgb(from var(--开启条目色) r g b / calc(alpha + 1));
}
/*关闭插件*/
.extension_block:not(:has(input[type="checkbox"]:checked)) {
    background: transparent;
    border: 2px solid transparent;
    opacity: var(--半透明);
}
/*关闭插件の字*/
.extensions_info .extension_disabled {
    color: var(--文本色);
}

/*插件の勾选框对齐*/
.extension_block {
    align-items: center !important;
}


/*〖❺.⑦.3 快速回复〗*/

#qr--global,
#qr--editor {
    margin-top: 5px;
}
/*「编辑快速回复」*/
#qr--editor > .qr--head {
    flex-direction: column;
    gap: 0 !important;
}
#qr--editor > .qr--head .qr--actions #qr--set {
    min-width: 10em;
}

/*Qr条目一行*/
#qr--settings #qr--set-qrList .qr--set-qrListContents > .qr--set-item .qr--content {
    align-items: center !important; 
    gap: 0 5px !important;
    padding: 0.5em 0 !important;
}
.qr--content {
    flex-wrap: wrap;
}

/*命名*/
.qr--content .qr--set-itemLabelContainer {
    max-width: 8em;
}

/*内容*/
.qr--content .qr--set-itemMessage {
    flex: 1 1 8em !important;
    field-sizing: content;
}

/*按钮*/
.qr--content .qr--actions {
    flex: 0 0 100% !important;
}


/*〖❺.⑦.4 正则〗*/

.regex-script-label {
    border-radius: var(--全局角) !important;
    padding: 0 0.5em 0 0.8em !important;
}
.regex_script_name {
    display: block !important;
    white-space: nowrap !important;
    text-decoration: none !important; /*去划线*/
}

/*开启の正则*/
.regex-script-label:not(:has(.disable_regex:checked)) {
    background: var(--开启条目色);
    border: 1px solid var(--开启条目色);
    font-weight: 500;
}
/*正则开启图标颜色*/
.regex-script-label .regex-toggle-on {
    color: var(--引用色) !important;
}

/*关闭の正则*/
.regex-script-label:has(.disable_regex:checked) {
    border: 1px solid transparent;
    opacity: var(--半透明);
}


/*〖❺.⑦.5 外部插件〗*/

/*〔酒馆助手〕*/
.p-0\.5,
.justify-center,
.text-\(--SmartThemeBodyColor\),
.py-\[3px\],
.p-1,
.p-\[5px\],
.bg-\(--grey5020a\) {
    border-radius: var(--全局角);
}
.p-\[5px\] {
    padding: 3px 0.5em 3px 1em;
}

/*脚本文件夹*/
.bg-\(--grey5020a\) {
    background-color: var(--背景色);
    border: 2px solid rgb(from var(--开启条目色) r g b / calc(alpha + 1));
}
div[data-type="folder"]:has([title="批量开关文件夹内脚本"]:not(.enabled)) {
    border: 2px dashed rgb(from var(--开启条目色) r g b / calc(alpha + 1)); 
    opacity: var(--微透明);
}
div[data-type="folder"]:has([title="批量开关文件夹内脚本"]:not(.enabled)) .flex.w-full.cursor-pointer.items-center.justify-between > span.grow {
    opacity: var(--不透明);
}

/*脚本开启条目*/
div[data-type="script"]:has(.fa-toggle-on) {
    background-color: var(--开启条目色);
    border: 1px solid rgb(from var(--开启条目色) r g b / calc(alpha + 0.2));
}
/*脚本关闭条目*/
div[data-type="script"]:has(.fa-toggle-off) {
    background-color: transparent;
    border: 1px dashed transparent;
    opacity: var(--半透明);
}
div[data-type="script"]:has(.fa-toggle-off) .opacity-50 {
    opacity: 1;
}
/*强制脚本名称单行*/
.ml-0\.5.overflow-hidden {
    display: block !important;
    white-space: nowrap !important;
}
/*脚本开启图标颜色*/
i.fa-solid.fa-toggle-on {
    color: var(--引用色);
}

/*〔Qr助手〕*/
.qr-icon-settings-layout,
.qr-icon-preview-box {
    border-radius: var(--全局角) !important;
    border-color: var(--边框色) !important;
    color:var(--文本色) !important;
}
.qr-icon-top-bar {
    border: none !important;
}


/*⋯⋯⋯⋯ ❺.⑧ User设定₈ ⋯⋯⋯⋯*/


/*〖❺.⑧.1 用户设定标题〗*/

div.flex-container:has(> .flex-container > #personas_backup) {
    flex-direction: column-reverse;
    margin-bottom: 1em;
}

/*第一行按钮*/
div.flex-container:has(> .flex-container > #personas_backup) > div.flex-container:has(> #personas_backup) {
    width: 100%;
    opacity: var(--半透明);
    justify-content: center;
}

/*第二行标题*/
div.flex-container:has(> .flex-container > #personas_backup) > div.flex-container:has(> h3) {
    position: relative;
    width: 100%;
    justify-content: center;
}
/*标题文字*/
div.flex-container:has(> .flex-container > #personas_backup) h3 {
    display: flex;
    width: 100%;
    font-size: 1.3em;
    justify-content: center;
}
/*问号靠右*/
div.flex-container:has(> .flex-container > #personas_backup) h3 > a {
    position: absolute;
    right: 0;
}


/*〖❺.⑧.2 用户选择〗*/

/*特殊提示*/
#persona_connections_info_block {
    border-radius: 0 var(--全局角) var(--全局角) 0;
    font-size: 0.9em;
    opacity: var(--微透明);
}

/*「更多」选择器单独一行*/
#persona_controls label[for="persona-management-dropdown"] {
    flex: 0 0 100%;
    margin-top: 0px;
    margin-bottom: 5px;
}

#persona_controls {
    flex-wrap: wrap;
    gap: 0;
}

/*用户切换选择*/
.avatar-container.interactable.selected,
.avatar-container.interactable:hover {
    border-radius: var(--全局角) !important;
    background: var(--开启条目色);
    border: 2px solid rgb(from var(--开启条目色) r g b / calc(alpha + 1)) !important;
}

/*用户选中放大*/
.avatar-container.interactable .avatar,
.avatar-container.interactable .ch_name {
    transition: transform 0.3s ease;
}
.avatar-container.interactable.selected .avatar,
.avatar-container.interactable.selected .ch_name {
    transform: scale(1.05);
    display: inline-block;
}

/*当前用户名称*/
#persona_controls .persona_name {
    opacity: var(--不透明);
    color: var(--引用色);
}
#persona_controls .persona_name:before {
    content: "「";
    color: var(--边框色);
    padding-right: 0.2em;
}
#persona_controls .persona_name:after {
    content: "」";
    color: var(--边框色);
    padding-left: 0.2em;
}

/*默认用户*/
.avatar-container.interactable.default_persona .avatar {
    position: relative;
    border-radius: var(--全局角) !important;
    outline-offset: -2px !important;
    outline: 3px solid var(--收藏图标色);
}
.avatar-container.interactable.default_persona .avatar::before {
    position: absolute;
    content: var(--收藏图标);
    top: var(--收藏图标上下);
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--收藏图标色);
    font-size: var(--收藏图标大小);
    font-weight: 500;
}
.default_persona .ch_name {
    color: var(--收藏图标色);
}


/*⋯⋯⋯⋯ ❺.⑨ Char设定₉ ⋯⋯⋯⋯*/


/*〖❺.⑨.1 角色设定外页〗*/

/*角色热切换*/
#HotSwapWrapper {
    min-width: 0;
}
/*滚动*/
.hotswap.avatars_inline.scroll-reset-container.expander {
    display: flex;
    overflow-x: auto;
    flex-wrap: nowrap;
    box-sizing: content-box;
    padding-bottom: 8px;
}

/*角色卡筛选*/
.rm_tag_controls {
    overflow-y: visible;
}

/*网格布局*/
#right-nav-panel-tabs {
    display: grid;
    grid-template-columns: 1fr; /* 单列布局 */
    align-items: center;
    width: 100%;
}

/*第一行 Token 信息 按钮*/
#result_info {
    grid-row: 1;
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    width: 100%;
    opacity: var(--半透明);
}
#result_info_text {
    margin-right: auto;
}

/*第二行 角色名*/
#rm_button_selected_ch {
    grid-row: 2;
    grid-column: 1 / -1;
    width: 100%;
    display: flex;
    justify-content: center;
    text-align: center;
    z-index: 1;
    opacity: var(--不透明);
    color: var(--引用色);
}
#rm_button_selected_ch h2 {
    font-size: 1.3em;
    white-space: nowrap;
    overflow: hidden; /*超出隐藏*/
    text-overflow: ellipsis;
    max-width: 100%;
}
#rm_button_selected_ch h2:before {
    content: "『";
    color: var(--边框色);
    padding-right: 0.2em;
}
#rm_button_selected_ch h2:after {
    content: "』";
    color: var(--边框色);
    padding-left: 0.2em;
}
/*名字悬停点击变色*/
#rm_button_selected_ch h2:hover {
    color: var(--文本色);
}
/*名字为空时隐藏这行*/
#rm_button_selected_ch:has(h2:empty) {
    display: none;
}

/*助理图标*/
.ch_assistant {
    text-align: center;
    width: 30%;
}

#rm_group_members, #rm_group_add_members {
    border-radius: var(--全局角) !important;
}

/*群聊*/
.group_select.is_fav .avatar,
.group_member.is_fav .avatar {
    position: relative;
    outline: none;
}
.group_select.is_fav .avatar::after,
.group_member.is_fav .avatar::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: var(--全局角);
    border: 3px solid var(--golden);
}

/*收藏角色*/
.character_select.entity_block.is_fav .avatar,
.avatar.is_fav {
    position: relative;
    border-radius: var(--全局角) !important;
    outline-offset: -2px !important;
    outline: 3px solid var(--收藏图标色);
}
.character_select.entity_block.is_fav .avatar::before {
    position: absolute;
    content: var(--收藏图标);
    top: var(--收藏图标上下);
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--收藏图标色);
    font-size: var(--收藏图标大小);
    font-weight: 500;
}
/*收藏角色姓名*/
.character_select.entity_block.is_fav .ch_name {
    color: var(--收藏图标色);
}

/*批量选中*/
#rm_print_characters_block.group_overlay_mode_select .character_select {
    background: none;
}
#rm_print_characters_block.group_overlay_mode_select .character_select.character_selected {
    background-color: var(--开启条目色);
}

/*悬停点击角色底边*/
.character_select.entity_block,
.group_select {
    border-radius: var(--全局角);
    background-color: transparent;
    border: 2px solid transparent;
}
.character_select.entity_block:hover,
.group_select:hover {
    background: var(--开启条目色);
    border: 2px solid rgb(from var(--开启条目色) r g b / calc(alpha + 1)) !important;
}

/*角色悬停选中放大*/
.character_select.entity_block .avatar,
.character_select.entity_block .ch_name {
    transition: transform 0.3s ease;
}
.character_select.entity_block:hover .avatar,
.character_select.entity_block:hover .ch_name {
    transform: scale(1.05);
    display: inline-block;
}


/*〖❺.⑨.2 角色设定内页〗*/

#avatar_div {
    flex-direction: column;
    align-items: center !important;
    gap: 0;
}
#avatar_controls {
    display: contents;
}

/*角色大头像*/
#avatar_div_div {
    zoom: 1.5;
    margin: 0;
}
/*更换角色头像*/
#avatar_div_div:hover{
    filter: none;
}
#avatar_div_div:hover #avatar_load_preview {
    outline: 3px dashed var(--次点色);
    outline-offset: -1.5px;
}

/*按钮组*/
.form_create_bottom_buttons_block {
    justify-content: center;
    margin: 5px 0 0 0;
}

/*「更多」选择器*/
label[for="char-management-dropdown"] {
    width: 100%;
}
#char-management-dropdown {
    margin-bottom: 5px;
}

/*创建搜索标签*/
body .ui-widget-content {
    box-shadow: none !important;
    border-radius: var(--全局角);
}
/*角色标签*/
.tag {
    text-shadow: none !important;
    border-radius: var(--全局角);
    border: 1px solid var(--边框色);
    opacity: var(--微透明) !important;
    padding: 0 0.3rem !important
}

/*角色标签管理弹窗*/
.title_restorable:has(.tag_view_prune) {
    flex-direction: column;
    align-items: center !important;
}
/*第二行按钮*/
.title_restorable:has(.tag_view_prune) .flex-container {
    justify-content: center !important;
    flex-wrap: wrap !important;
    width: 100% !important;
    margin-bottom: 0.5em;
}




/*☆★☆★☆★☆★☆★☆★☆★☆★☆★*/
